with open('./challenge/table.txt', 'r') as f:
    content = f.read()

lines = content.strip().split('\n')
# Skip header lines
for i, line in enumerate(lines):
    if '|' in line:
        parts = line.split('|')
        row_label = parts[0].strip()
        cells = parts[1].split()
        # Check if this is a standard Vigenere row
        expected = []
        for j in range(26):
            expected.append(chr(ord('A') + (ord(row_label) - ord('A') + j) % 26))
        if cells != expected:
            print(f"Row {row_label} differs at position {j}: got {cells}, expected {expected}")
            for j in range(26):
                if cells[j] != expected[j]:
                    print(f"  Position {j}: got '{cells[j]}', expected '{expected[j]}'")

print("Check complete")"}
